/bin/bash -lc "cat > /workspace/openai_client.py <<'PY'
\"\"\"Minimal standard-library client for OpenAI's Responses API.

Prompts and API keys are kept in memory only. The client does not log request
or response content; provide the API key through "'``OPENAI_API_KEY`` or the
``api_key`` argument.
"""

from __future__ import annotations

import json
import os
from typing import Any
from urllib.error import HTTPError, URLError
from urllib.request import Request, urlopen


API_URL = "https://api.openai.com/v1/responses"


class OpenAIAPIError(RuntimeError):
    """An API request failed without exposing prompt or response contents."""


def create_response(
    prompt: str,
    model: str = "gpt-4.1-mini",
    *,
    api_key: str | None = None,
    timeout: float = 60.0,
) -> dict[str, Any]:
    """Send a text prompt to the Responses API and return its JSON response.

    The API key defaults to the ``OPENAI_API_KEY`` environment variable. This
    function does not persist or print the prompt, key, or API response.
    """
    if not isinstance(prompt, str):
        raise TypeError("prompt must be a string")
    if not isinstance(model, str) or not model:
        raise ValueError("model must be a non-empty string")
    if timeout <= 0:
        raise ValueError("timeout must be greater than zero")

    key = api_key or os.environ.get("OPENAI_API_KEY")
    if not key:
        raise ValueError("Set OPENAI_API_KEY or pass api_key")

    payload = json.dumps({"model": model, "input": prompt}).encode("utf-8")
    request = Request(
        API_URL,
        data=payload,
        headers={
            "Authorization": f"Bearer {key}",
            "Content-Type": "application/json",
        },
        method="POST",
    )

    try:
        with urlopen(request, timeout=timeout) as response:
            result = json.loads(response.read().decode("utf-8"))
    except HTTPError as error:
        raise OpenAIAPIError(
            f"OpenAI API request failed with HTTP {error.code}"
        ) from None
    except URLError as error:
        raise OpenAIAPIError(
            f"Could not reach OpenAI API: {error.reason}"
        ) from None
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise OpenAIAPIError("OpenAI API returned an invalid JSON response") from None

    if not isinstance(result, dict):
        raise OpenAIAPIError("OpenAI API returned an unexpected response")
    return result


def output_text(response: dict[str, Any]) -> str:
    """Extract generated text from a Responses API response object."""
    parts: list[str] = []
    for item in response.get("output", []):
        if not isinstance(item, dict):
            continue
        for content in item.get("content", []):
            if (
                isinstance(content, dict)
                and content.get("type") == "output_text"
                and isinstance(content.get("text"), str)
            ):
                parts.append(content["text"])
    return "".join(parts)
