import json
import openai_client

class MockResponse:
    def __enter__(self):
        return self

    def __exit__(self, *args):
        return False

    def read(self):
        return json.dumps({\"output\": [{\"content\": [{\"type\": \"output_text\", \"text\": \"ok\"}]}]}).encode()

captured = {}
def fake_urlopen(request, timeout):
    captured[\"url\"] = request.full_url
    captured[\"method\"] = request.method
    captured[\"headers\"] = request.headers
    captured[\"body\"] = json.loads(request.data)
    captured[\"timeout\"] = timeout
    return MockResponse()

openai_client.urlopen = fake_urlopen
result = openai_client.create_response(\"private prompt\", api_key=\"test-key\")
assert captured[\"url\"] == openai_client.API_URL
assert captured[\"method\"] == \"POST\"
assert captured[\"headers\"][\"Authorization\"] == \"Bearer test-key\"
assert captured[\"body\"] == {\"model\": \"gpt-4.1-mini\", \"input\": \"private prompt\"}
assert openai_client.output_text(result) == \"ok\"
print(\"Mocked Responses API request and text extraction passed.\")
